import {escapeHtml as e} from '../shared/utils.js?v=0.19.0';
import {sourceDetails} from '../shared/ancestry-ui.js?v=0.19.0';
import {derivedFrom} from '../shared/ancestry.js?v=0.19.0';
import {JUDGEMENTS,TREATMENTS,OPTION_LABELS,analysisChanged,responseSummary} from './transfers.js?v=0.19.0';
const text=(a,key,prompt='')=>`<div class="field"><label for="option-${key}">${e(OPTION_LABELS[key])}</label>${prompt?`<p>${e(prompt)}</p>`:''}<textarea id="option-${key}" data-edit="option-edit" data-id="${e(a.id)}" data-field="${key}" rows="2" maxlength="20000">${e(a[key])}</textarea></div>`;
function relationshipResponse(a,r,i){return `<details class="response-item" id="response-${e(a.id)}-${i}"><summary><span class="response-number">${String(i+1).padStart(2,'0')}</span><span><strong>${e(r.sourceRelation||'Unnamed relationship')}</strong><span class="response-status">${e(TREATMENTS[r.treatment])}${r.reason.trim()?' · reason written':''}</span></span><span class="fit-tag fit-${r.fit}">${JUDGEMENTS[r.fit]}${r.stale?' · recheck':''}</span></summary><div class="response-content"><div class="response-context"><div><span class="eyebrow">SOURCE AT CAPTURE</span><p>${e(r.sourceFrom)} → ${e(r.sourceTo)}</p><p>${e(r.sourceRelation)}</p></div><div><span class="eyebrow">TARGET AT CAPTURE</span><p>${e(r.targetFrom)} → ${e(r.targetTo)}</p><p>${e(r.targetRelation||'Target interaction not yet described.')}</p></div></div>${r.note?`<p><b>Earlier reasoning:</b> ${e(r.note)}</p>`:''}<div class="response-context"><p><b>Needs:</b> ${e(r.condition||'Condition not recorded.')}</p><p><b>Breaks if:</b> ${e(r.failure||'Failure point not recorded.')}</p></div><div class="field"><label for="response-treatment-${i}">What does this adaptation do with it?</label><select id="response-treatment-${i}" data-edit="option-response" data-id="${e(a.id)}" data-link-id="${e(r.id)}" data-field="treatment">${Object.entries(TREATMENTS).map(([key,label])=>`<option value="${key}" ${key===r.treatment?'selected':''}>${label}</option>`).join('')}</select></div><div class="response-context"><div class="field"><label for="response-rewrite-${i}">The interaction in this adaptation</label><p>If leaving it out, name what replaces it or what is lost.</p><textarea id="response-rewrite-${i}" data-edit="option-response" data-id="${e(a.id)}" data-link-id="${e(r.id)}" data-field="rewrite" maxlength="20000" rows="2">${e(r.rewrite)}</textarea></div><div class="field"><label for="response-reason-${i}">Why this treatment?</label><p>Explain how it addresses the mismatch and what still has to be true.</p><textarea id="response-reason-${i}" data-edit="option-response" data-id="${e(a.id)}" data-link-id="${e(r.id)}" data-field="reason" maxlength="20000" rows="2">${e(r.reason)}</textarea></div></div></div></details>`;}
export function basisNotice(w,a){return analysisChanged(w,a)?`<div class="basis-notice"><p>This adaptation uses an earlier or different analysis. Its source wording and relationship responses stay intact.</p><button class="button" data-action="option-recast" data-id="${e(a.id)}">Try the current mapping as a new branch</button><p class="microcopy">Keeps this adaptation; the new branch starts with undecided responses to the current relationships.</p></div>`:'<p class="basis-current">Source record matches the current analysis.</p>';}
function editor(w,a){return `<section class="option-editor" id="option-editor" aria-label="Develop an adaptation"><header class="option-heading"><div><span class="eyebrow">${a.ancestry.parked?'PARKED ALTERNATIVE':'BORROW DELIBERATELY'}</span><h3>Develop this adaptation</h3></div><div class="toolbar"><button class="button" data-action="option-branch" data-id="${e(a.id)}">Branch a variation</button><button class="button" data-action="option-park" data-id="${e(a.id)}">${a.ancestry.parked?'Revive':'Park'}</button><button class="text-button" data-action="option-remove" data-id="${e(a.id)}">Remove</button></div></header><div id="option-basis-notice">${basisNotice(w,a)}</div>${sourceDetails(derivedFrom([a.basis]))}${a.ancestry.parents.length?sourceDetails(a.ancestry):''}<div class="option-columns"><div>${text(a,'title')}${text(a,'mechanism','State the principle without relying on the metaphor.')}</div>${text(a,'adaptation','Which role, rule, signal or interaction changes?')}</div>${a.ancestry.parents.length?`<details id="option-branch-reason" open><summary>What changes and why?</summary><div class="option-columns">${text(a,'changed')}${text(a,'reason')}</div></details>`:''}<section class="relationship-responses"><h3>What to keep, change or leave out</h3><p>Open each relationship to decide how this alternative handles it. A mismatch can become a design requirement.</p>${a.relationships.map((r,i)=>relationshipResponse(a,r,i)).join('')||'<p>No relationships were recorded in this source. Develop the mapping before borrowing it.</p>'}</section><details class="option-test" id="option-test" open><summary>Boundaries and a test</summary>${text(a,'boundary','Which assumptions remain, and what cannot be copied?')}<div class="option-columns">${text(a,'test','Who tries what, for how long, with what limit on effort?')}${text(a,'learn','An observation that would make you revise or stop.')}</div></details></section>`;}
export const compareValue=(a,key)=>key==='source'?a.basis.title:key==='responses'?responseSummary(a):a[key];
const rows=[['Borrowed source','source'],['Working principle','mechanism'],['Adaptation','adaptation'],['Relationship decisions','responses'],['Boundaries','boundary'],['Smallest test','test'],['Revise or stop if','learn']];
function compare(w){const options=w.compareOptions.map(id=>w.options.find(a=>a.id===id));return `<section class="options-comparison" id="options-comparison"><h3>Which adaptation is worth testing?</h3><p>Compare different responses to a mismatch, or borrow from different sources. These are hypotheses, not proven equivalences.</p>${options.length?`<p class="microcopy">Scroll sideways to compare adaptations ↔</p><div class="options-scroll" tabindex="0" role="region" aria-label="Adaptation comparison; scroll sideways"><table><thead><tr><th scope="col">Compare</th>${options.map(a=>`<th scope="col"><button class="text-button" data-action="option-select" data-id="${e(a.id)}">${e(a.title||'Untitled adaptation')}</button><button class="button ${a.id===w.chosenOptionId?'primary':''}" data-action="option-choose" data-id="${e(a.id)}" aria-pressed="${a.id===w.chosenOptionId}">${a.id===w.chosenOptionId?'Chosen test':'Choose this test'}</button></th>`).join('')}</tr></thead><tbody>${rows.map(([label,key])=>`<tr><th scope="row">${label}</th>${options.map(a=>`<td data-compare-id="${e(a.id)}" data-compare-field="${key}">${e(compareValue(a,key)||'Not written.')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<p>Choose up to four alternatives from the collection.</p>'}<div class="field"><label for="option-decision">Why this test, and what remains uncertain?</label><textarea id="option-decision" data-edit="option-decision" maxlength="20000" rows="2">${e(w.decision)}</textarea></div></section>`;}
export function transfersPanel(w){const selected=w.options.find(a=>a.id===w.selectedOptionId);const cards=items=>items.map(a=>`<article class="option-card ${a.id===w.selectedOptionId?'selected':''}"><span class="eyebrow">${e(a.basis.title)}</span><button class="option-title" data-action="option-select" data-id="${e(a.id)}" aria-pressed="${a.id===w.selectedOptionId}">${e(a.title||'Untitled adaptation')}</button><p data-option-preview="${e(a.id)}">${e(a.adaptation.slice(0,220)||'Adaptation to develop.')}${a.adaptation.length>220?'…':''}</p><p class="microcopy" data-option-summary="${e(a.id)}">${e(responseSummary(a))}</p>${a.ancestry.parked?'<span class="fit-tag">Parked</span>':`<label class="compare-option"><input type="checkbox" data-action="option-compare" data-id="${e(a.id)}" ${w.compareOptions.includes(a.id)?'checked':''}> Compare</label>`}${w.chosenOptionId===a.id?'<p class="chosen-option">Chosen test</p>':''}</article>`).join('');return `<section class="saved-options" id="saved-options"><header class="option-heading"><div><span class="eyebrow">PRACTICAL ALTERNATIVES</span><h3>Keep more than one way to borrow</h3></div>${w.options.length?'<button class="button" data-action="option-family">Follow branches</button>':''}</header>${w.options.length?`<div class="option-collection">${cards(w.options.filter(a=>!a.ancestry.parked))}</div>${w.options.some(a=>a.ancestry.parked)?`<details id="parked-options"><summary>Parked adaptations</summary><div class="option-collection">${cards(w.options.filter(a=>a.ancestry.parked))}</div></details>`:''}${selected?editor(w,selected):''}${compare(w)}`:'<p>Capture the draft above to retain its source analysis, develop relationship responses and branch other adaptations.</p>'}</section>`;}
export function refreshTransfers(root,w){
 const selected=w.options.find(a=>a.id===w.selectedOptionId),notice=root.querySelector('#option-basis-notice');if(selected&&notice)notice.innerHTML=basisNotice(w,selected);
 for(const a of w.options){root.querySelectorAll('[data-action="option-select"]').forEach(el=>{if(el.dataset.id===a.id)el.textContent=a.title||'Untitled adaptation';});root.querySelectorAll('[data-option-preview]').forEach(el=>{if(el.dataset.optionPreview===a.id)el.textContent=(a.adaptation.slice(0,220)||'Adaptation to develop.')+(a.adaptation.length>220?'…':'');});root.querySelectorAll('[data-option-summary]').forEach(el=>{if(el.dataset.optionSummary===a.id)el.textContent=responseSummary(a);});root.querySelectorAll('[data-compare-id]').forEach(el=>{if(el.dataset.compareId===a.id)el.textContent=compareValue(a,el.dataset.compareField)||'Not written.';});}
 if(selected)selected.relationships.forEach((r,i)=>{const el=document.getElementById(`response-${selected.id}-${i}`)?.querySelector('.response-status');if(el)el.textContent=TREATMENTS[r.treatment]+(r.reason.trim()?' · reason written':'');});
}
